WITH with_last AS (SELECT s.id, s.product_name, s.stock_qty, s.supplier_id, x.quantity, x.last_restock FROM products s JOIN LATERAL (SELECT c.quantity, c.last_restock FROM inventory c WHERE c.product_id = s.id AND c.last_restock <= s.launch_date ORDER BY c.last_restock DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT s.id, s.supplier_id, s.quantity, (SELECT SUM(p2.cost) FROM products p2 WHERE p2.supplier_id = s.supplier_id) AS sum_product_cost FROM with_last s;
